var a=[{title:`Cum funcționează intervalele`,text:`Un interval de efort îți crește respirația și volumul de muncă, iar intervalul de recuperare te lasă să te refaci parțial sau în mare parte. Le poți ajusta pe amândouă. Intervalele pot fi aerobe, cum ar fi mersul alert alternat cu mers ușor, sau mai grele, cum ar fi o repriză rapidă de ciclism urmată de pedalat ușor.`},{title:`Începe sub efortul maxim`,text:`Dacă ești nou în exerciții, poți alterna un minut de mers alert cu două minute de mers confortabil, timp de șase runde. Un alergător experimentat poate folosi eforturi mai rapide cu odihnă mai lungă. Viteza potrivită de lucru depinde de nivelul tău și de exercițiu, așa că un raport de timp singur nu îți spune cât de greu este efortul pentru corpul tău.`},{title:`Durata recuperării depinde de obiectiv`,text:`Recuperările mai lungi păstrează viteza și calitatea mișcării ridicate la repetările intense. Recuperările mai scurte fac sesiunea mai continuă și pot crește solicitarea generală a inimii și plămânilor, dar dacă sunt prea scurte, calitatea scade repede. Stabilește efortul și odihna ca să corespundă obiectivului de condiție fizică pe care îl ai în vedere.`},{title:`Controlează încărcarea totală`,text:`Încălzește-te mereu treptat și termină cu ceva mai ușor. Crește cantitatea totală de muncă pe intervale înainte să faci intervalele mult mai grele. Dacă forma mersului, mecanica alergării sau coordonarea la sfoara de sărit încep să se strice, ia o recuperare mai lungă, scade intensitatea sau încheie sesiunea.`},{title:`Folosirea TrainUp`,text:`Cronometrul de odihnă și cel de menținere îți țin intervalele la timp, iar după antrenament evaluezi efortul sesiunii de la 1 la 10. Mai greu nu înseamnă automat mai bine. Când îți regenerezi planul, acesta devine mai ușor dacă 2 din ultimele tale 3 antrenamente au fost foarte grele (RPE 9 sau mai mult) sau finalizate sub 60%, și cu un pas mai greu doar dacă ultimele 4 au fost ușoare și complete. Dacă ai nevoie de mai puțin impact, ciclismul sau marșul rapid funcționează și ca intervale.`}];var t=[{label:`ACE: proiectarea intervalelor de intensitate mare`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: măsurarea intensității activității și testul vorbirii`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: recomandări de activitate fizică pentru adulți`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};